/**
 * Generates src/generated/grid.css and src/generated/utilities.css
 * from framework.config.mjs. Run via `npm run build` (or `npm run generate`).
 * Don't hand-edit the generated files — they get overwritten.
 */
import { writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const config = (await import(pathToFileURL(join(root, 'framework.config.mjs')).href)).default;

const bps = Object.entries(config.breakpoints); // [['sm',576],…]
const HEADER = (name) =>
  `/* ==========================================================================\n` +
  `   makr.css — ${name}\n` +
  `   GENERATED by scripts/generate.mjs from framework.config.mjs. Don't edit.\n` +
  `   ========================================================================== */\n`;

const pct = (n) => `${+(n * 100).toFixed(6)}%`;
const rule = (sel, decls, imp = false) =>
  `${sel} { ${decls.map(([p, v]) => `${p}: ${v}${imp ? ' !important' : ''};`).join(' ')} }`;

/** emit a block for "no breakpoint" and each breakpoint (infix like "-md") */
function responsive(build, enabled = true) {
  let out = build('') + '\n';
  if (!enabled) return out;
  const list = Array.isArray(enabled) ? bps.filter(([bp]) => enabled.includes(bp)) : bps;
  for (const [bp, px] of list) {
    out += `\n@media (min-width: ${px}px) {\n${indent(build(`-${bp}`))}\n}\n`;
  }
  return out;
}
const indent = (s) => s.split('\n').map((l) => (l ? '  ' + l : l)).join('\n');

/* ----------------------------------------------------------------------- */
/* GRID                                                                     */
/* ----------------------------------------------------------------------- */
const cols = config.columns;
function gridBlock(infix) {
  const r = [];
  r.push(rule(`.col${infix}`, [['flex', '1 0 0%']]));
  r.push(rule(`.row-cols${infix}-auto > *`, [['flex', '0 0 auto'], ['width', 'auto']]));
  for (let i = 1; i <= config.rowCols; i++)
    r.push(rule(`.row-cols${infix}-${i} > *`, [['flex', '0 0 auto'], ['width', pct(1 / i)]]));
  r.push(rule(`.col${infix}-auto`, [['flex', '0 0 auto'], ['width', 'auto']]));
  for (let i = 1; i <= cols; i++)
    r.push(rule(`.col${infix}-${i}`, [['flex', '0 0 auto'], ['width', pct(i / cols)]]));
  for (let i = 0; i < cols; i++)
    r.push(rule(`.offset${infix}-${i}`, [['margin-left', i === 0 ? '0' : pct(i / cols)]]));
  for (const k of config.gutterKeys) {
    const v = `var(--space-${k})`;
    r.push(rule(`.g${infix}-${k}`, [['--gutter-x', v], ['--gutter-y', v]]));
    r.push(rule(`.gx${infix}-${k}`, [['--gutter-x', v]]));
    r.push(rule(`.gy${infix}-${k}`, [['--gutter-y', v]]));
  }
  r.push(rule(`.order${infix}-first`, [['order', '-1']]));
  for (let i = 0; i <= 5; i++) r.push(rule(`.order${infix}-${i}`, [['order', String(i)]]));
  r.push(rule(`.order${infix}-last`, [['order', '6']]));
  return r.join('\n');
}

/* ----------------------------------------------------------------------- */
/* UTILITIES                                                                */
/* ----------------------------------------------------------------------- */
const R = config.responsive;
const displays = ['none', 'inline', 'inline-block', 'block', 'grid', 'inline-grid', 'flex', 'inline-flex', 'contents'];
const justify = { start: 'flex-start', end: 'flex-end', center: 'center', between: 'space-between', around: 'space-around', evenly: 'space-evenly' };
const alignItems = { start: 'flex-start', end: 'flex-end', center: 'center', baseline: 'baseline', stretch: 'stretch' };
const alignSelf = { auto: 'auto', ...alignItems };
const alignContent = { start: 'flex-start', end: 'flex-end', center: 'center', between: 'space-between', around: 'space-around', stretch: 'stretch' };
const space = (k) => (k === 0 ? '0' : `var(--space-${k})`);

function displayBlock(i) {
  return displays.map((d) => rule(`.d${i}-${d}`, [['display', d]], true)).join('\n');
}
function flexBlock(i) {
  const r = [];
  for (const d of ['row', 'column', 'row-reverse', 'column-reverse'])
    r.push(rule(`.flex${i}-${d}`, [['flex-direction', d]], true));
  for (const w of ['wrap', 'nowrap', 'wrap-reverse']) r.push(rule(`.flex${i}-${w}`, [['flex-wrap', w]], true));
  r.push(rule(`.flex${i}-fill`, [['flex', '1 1 auto']], true));
  r.push(rule(`.flex${i}-grow-0`, [['flex-grow', '0']], true));
  r.push(rule(`.flex${i}-grow-1`, [['flex-grow', '1']], true));
  r.push(rule(`.flex${i}-shrink-0`, [['flex-shrink', '0']], true));
  r.push(rule(`.flex${i}-shrink-1`, [['flex-shrink', '1']], true));
  for (const [k, v] of Object.entries(justify)) r.push(rule(`.justify-content${i}-${k}`, [['justify-content', v]], true));
  for (const [k, v] of Object.entries(alignItems)) r.push(rule(`.align-items${i}-${k}`, [['align-items', v]], true));
  for (const [k, v] of Object.entries(alignSelf)) r.push(rule(`.align-self${i}-${k}`, [['align-self', v]], true));
  for (const [k, v] of Object.entries(alignContent)) r.push(rule(`.align-content${i}-${k}`, [['align-content', v]], true));
  return r.join('\n');
}
function gapBlock(i) {
  const r = [];
  for (const k of config.spacingKeys) {
    r.push(rule(`.gap${i}-${k}`, [['gap', space(k)]], true));
    r.push(rule(`.row-gap${i}-${k}`, [['row-gap', space(k)]], true));
    r.push(rule(`.column-gap${i}-${k}`, [['column-gap', space(k)]], true));
  }
  return r.join('\n');
}
const sides = {
  '': ['{p}'],
  t: ['{p}-top'], b: ['{p}-bottom'], l: ['{p}-left'], r: ['{p}-right'],
  x: ['{p}-left', '{p}-right'], y: ['{p}-top', '{p}-bottom'],
};
function spacingBlock(i) {
  const r = [];
  for (const [abbr, prop] of [['m', 'margin'], ['p', 'padding']]) {
    for (const [s, props] of Object.entries(sides)) {
      const keys = [...config.spacingKeys, ...(abbr === 'm' ? ['auto'] : [])];
      for (const k of keys) {
        const v = k === 'auto' ? 'auto' : space(k);
        r.push(rule(`.${abbr}${s}${i}-${k}`, props.map((p) => [p.replace('{p}', prop), v]), true));
      }
    }
  }
  return r.join('\n');
}
function textBlock(i) {
  return [
    rule(`.text${i}-left, .text${i}-start`, [['text-align', 'left']], true),
    rule(`.text${i}-center`, [['text-align', 'center']], true),
    rule(`.text${i}-right, .text${i}-end`, [['text-align', 'right']], true),
  ].join('\n');
}

let grid = HEADER('Grid columns, offsets, gutters, order') + '\n';
grid += responsive(gridBlock, R.order !== false);

let utils = HEADER('Responsive utilities') + '\n';
utils += '/* ---- Display ---- */\n' + responsive(displayBlock, R.display);
utils += '\n/* ---- Flexbox ---- */\n' + responsive(flexBlock, R.flex);
utils += '\n/* ---- Gap ---- */\n' + responsive(gapBlock, R.gap);
utils += '\n/* ---- Text align ---- */\n' + responsive(textBlock, R.text);
utils += '\n/* ---- Spacing (margin / padding) ---- */\n' + responsive(spacingBlock, R.spacing);

const outDir = join(root, 'src', 'generated');
mkdirSync(outDir, { recursive: true });
writeFileSync(join(outDir, 'grid.css'), grid);
writeFileSync(join(outDir, 'utilities.css'), utils);
console.log(`generated grid.css (${(grid.length / 1024).toFixed(1)} KB) and utilities.css (${(utils.length / 1024).toFixed(1)} KB)`);
